global_max_col = max(all_demo_specials)

# Theory 9: When ALL gaps are ≤1 (very small), fill ALL gap cells completely
# Instead of edge-only filling

output = []
for r in range(h):
    result_row = list(test_in[r])
    row_specials = [c for c in range(w) if test_in[r][c] == special_val]
    n_specs = len(row_specials)

    if n_specs == 0:
        pass
    elif n_specs == 1:
        local_spec = row_specials[0]
        if local_spec != global_min_col:
            result_row[global_min_col] = 2
        elif local_spec != global_max_col:
            result_row[global_max_col] = 2
    else:
        # Check if ALL gaps are very small (≤1)
        all_very_small_gaps = True
        for i in range(n_specs - 1):
            gap_len = row_specials[i+1] - row_specials[i] - 1
            if gap_len > 1:  # Using >1 instead of >2
                all_very_small_gaps = False
                break

        if all_very_small_gaps:
            # Fill ALL gap cells completely
            for left, right in zip(row_specials[:-1], row_specials[1:]):
                gap_cells = list(range(left + 1, right))
                for c in gap_cells:
                    result_row[c] = 2
        else:
            local_min = min(row_specials)
            local_max = max(row_specials)

            if local_min > global_min_col:
                for c in range(global_min_col, local_min):
                    result_row[c] = 2
            if local_max < global_max_col:
                for c in range(local_max + 1, global_max_col + 1):
                    result_row[c] = 2

            small_gaps_test = True
            for i in range(n_specs - 1):
                gap_len = row_specials[i+1] - row_specials[i] - 1
                if gap_len > 2:
                    small_gaps_test = False
                    break

            if small_gaps_test:
                for left, right in zip(row_specials[:-1], row_specials[1:]):
                    gap_cells = list(range(left + 1, right))
                    if len(gap_cells) >= 2:
                        result_row[gap_cells[0]] = 2
                        result_row[gap_cells[-1]] = 2
                    elif len(gap_cells) == 1:
                        result_row[gap_cells[0]] = 2
            else:
                for c in range(local_min + 1, local_max):
                    if test_in[r][c] == bg:
                        result_row[c] = 2

    output.append(result_row)

print("Theory 9: All gaps ≤1 → fill completely")
